package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.jobs.SourceContractFacts;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class SourceContractMonitoringCycleTest {
 static final Key KEY=new Key("OPS-07","collector","fictional-source");
 SourceContractFacts.Evidence evidence(OperationalPersistenceFixture f,long count){return new SourceContractFacts.Evidence(KEY.resourceKey(),1,"a".repeat(64),count,count,1,f.clock.now,f.clock.now,f.clock.now,f.clock.now);}
 SourceContractMonitoringCycle cycle(OperationalPersistenceFixture f,SourceContractFacts.Api api){var store=f.store();var cycle=new SourceContractMonitoringCycle(KEY,api,store,f.monitor(store),f.clock);cycle.start();return cycle;}
 @Test void nativeZeroSamplesOnceAndRestartSkipsOriginalProvider(){var f=new OperationalPersistenceFixture();var count=new AtomicInteger();SourceContractFacts.Api api=id->{assertEquals(KEY.resourceKey(),id);assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());count.incrementAndGet();return evidence(f,0);};assertEquals(SourceContractMonitoringCycle.Outcome.SAMPLED,cycle(f,api).tick());assertEquals(Status.NORMAL,f.store().read(KEY).status());assertEquals(SourceContractMonitoringCycle.Outcome.ALREADY_SAMPLED,cycle(f,api).tick());assertEquals(1,count.get());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));}
 @Test void nativeErrorsMissingAcquisitionAndRecreatedSummaryKeepOriginalGuard(){var f=new OperationalPersistenceFixture();cycle(f,id->evidence(f,3)).tick();assertEquals(Level.CRITICAL,f.store().read(KEY).level());assertTrue(f.store().read(KEY).guards().contains(Guard.NEW_FETCH));f.clock.now=f.clock.now.plusSeconds(60);cycle(f,id->null).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());assertEquals(3,f.store().read(KEY).counters().get("source_total"));assertTrue(f.store().read(KEY).guards().contains(Guard.NEW_FETCH));f.clock.now=f.clock.now.plusSeconds(60);cycle(f,id->{throw new IllegalStateException("fictional unavailable");}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));}
 @Test void crossMinuteStaleOrFutureProofAndDefaultStoppedStayUnknown(){var f=new OperationalPersistenceFixture();var store=f.store();var stopped=new SourceContractMonitoringCycle(KEY,id->{fail("startup cannot read facts");return null;},store,f.monitor(store),f.clock);assertEquals(SourceContractMonitoringCycle.Outcome.STOPPED,stopped.tick());assertNull(store.read(KEY));cycle(f,id->{var e=evidence(f,0);f.clock.now=f.clock.now.plusSeconds(60);return e;}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,store.read(KEY).status());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,id->{Instant old=f.clock.now.minusSeconds(121);return new SourceContractFacts.Evidence(id,1,"a".repeat(64),0,0,1,old,old,old,old);}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,store.read(KEY).status());assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(f.tx).execute(s->cycle(f,id->evidence(f,0)).tick()));}
 @Test void singleFlightStopAndCompletedReadNeverWriteAfterStopping()throws Exception{var f=new OperationalPersistenceFixture();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var cycle=cycle(f,id->{entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}return evidence(f,0);});var pool=Executors.newSingleThreadExecutor();try{var first=pool.submit(cycle::tick);assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(SourceContractMonitoringCycle.Outcome.BUSY,cycle.tick());cycle.stop();release.countDown();assertEquals(SourceContractMonitoringCycle.Outcome.STOPPED,first.get(5,TimeUnit.SECONDS));assertNull(f.store().read(KEY));}finally{release.countDown();pool.shutdownNow();}}
}
